    /// Handle sudden or planned network interface drop across all multiplexed transport sessions in the pool.
    pub fn handle_interface_down(
        &self,
        interface_name: &str,
        now: std::time::Instant,
    ) -> MultiInterfaceFailoverReport {
        let report = if let Ok(mut arb) = self.inter_session_arbitrator.lock() {
            arb.handle_interface_down(interface_name, now)
        } else {
            MultiInterfaceFailoverReport {
                interface_down: interface_name.to_string(),
                active_interfaces_remaining: Vec::new(),
                sessions_affected: 0,
                quic_migrations: 0,
                http2_failovers: 0,
                streams_preserved: 0,
                bytes_preserved: 0,
                events: Vec::new(),
            }
        };

        if self
            .enable_shared_header_compression
            .load(std::sync::atomic::Ordering::Relaxed)
        {
            if let Ok(mut mgr) = self.shared_header_compression_manager.lock() {
                for ev in &report.events {
                    if ev.success {
                        mgr.record_failover_migration(&ev.origin, ev.session_id, ev.protocol, now);
                    }
                }
            }
        }

        report
    }

