    #[test]
    fn test_http2_push_promise_automated_caching_and_cache_hit() {
        let listener = AsyncTcpListener::bind("127.0.0.1:0").expect("bind listener");
        let port = listener.local_addr().expect("local addr").port();

        let server_handle = std::thread::spawn(move || {
            let mut server = loop {
                match listener.accept() {
                    Ok((stream, _)) => match AsyncHttp2Connection::server_handshake(stream) {
                        Ok(conn) => break conn,
                        Err(_) => continue,
                    },
                    Err(_) => std::thread::sleep(Duration::from_millis(5)),
                }
            };

            // Await initial client request on stream 1
            let mut req_stream_id = 0;
            for _ in 0..30 {
                match server.recv_frame() {
                    Ok(crate::simd_parser::Http2Frame::Headers { stream_id, .. }) => {
                        req_stream_id = stream_id;
                        break;
                    }
                    _ => std::thread::sleep(Duration::from_millis(5)),
                }
            }
            assert_eq!(req_stream_id, 1);

            // 1. Send PUSH_PROMISE frame on stream 1 reserving stream 2 for /style.css
            let push_promise = server.session.create_push_promise(
                1,
                2,
                &[
                    (":method", "GET"),
                    (":path", "/style.css"),
                    (":scheme", "http"),
                ],
            );
            server.send_frame(&push_promise).expect("send push promise");

            // 2. Transmit promised response on stream 2
            let push_headers = [(":status", "200"), ("content-type", "text/css")];
            server
                .send_response(2, &push_headers, Some(b"body { background: #fff; }"))
                .expect("send promised response");

            // 3. Transmit response for original request stream 1
            let html_headers = [(":status", "200"), ("content-type", "text/html")];
            server
                .send_response(1, &html_headers, Some(b"<html>hello push</html>"))
                .expect("send stream 1 response");

            // Keep connection open while client consumes and performs checks
            for _ in 0..10 {
                let _ = server.try_recv_frame();
                std::thread::sleep(Duration::from_millis(5));
            }
        });

        let pool = AsyncHttp2Pool::new("127.0.0.1", port, 2).with_push_promises(true);
        assert!(pool.push_promises_enabled());
        assert_eq!(pool.push_promises_received(), 0);
        assert_eq!(pool.push_cache_hits(), 0);

        // 1. Execute initial request for /index.html
        let resp_html = pool
            .execute_request("GET", "/index.html", &[], None)
            .expect("execute request index.html");
        assert_eq!(resp_html.status.0, 200);
        assert_eq!(resp_html.body, b"<html>hello push</html>");

        // The push promise for /style.css must have been automatically absorbed and cached in the pool
        assert!(pool.has_cached_push_response("GET", "/style.css"));
        assert_eq!(pool.push_promises_received(), 1);
        assert_eq!(pool.push_promise_cache_count(), 1);
        assert_eq!(pool.stats().cached_push_promises, 1);

        // 2. Execute subsequent request for /style.css -> MUST be a proactive Cache Hit without network round-trip!
        let resp_css = pool
            .execute_request("GET", "/style.css", &[], None)
            .expect("execute request style.css from push cache");
        assert_eq!(resp_css.status.0, 200);
        assert_eq!(resp_css.body, b"body { background: #fff; }");

        // Cache hit counter incremented and cache entry consumed
        assert_eq!(pool.push_cache_hits(), 1);
        assert_eq!(pool.push_promise_cache_count(), 0);
        assert_eq!(pool.stats().push_cache_hits, 1);
        assert!(!pool.has_cached_push_response("GET", "/style.css"));

        server_handle.join().expect("server join");
    }

    #[test]
    fn test_http2_push_promise_disabled_pool_configuration() {
        let pool = AsyncHttp2Pool::new("127.0.0.1", 8080, 2).with_push_promises(false);
        assert!(!pool.push_promises_enabled());
        assert_eq!(pool.push_promise_cache_count(), 0);
        assert_eq!(pool.push_promises_received(), 0);
        assert_eq!(pool.push_cache_hits(), 0);

        pool.clear_push_promise_cache();
        assert_eq!(pool.push_promise_cache_count(), 0);
    }

    #[test]
    fn test_http2_push_promise_rfc7234_freshness_and_no_store() {
        let listener = AsyncTcpListener::bind("127.0.0.1:0").expect("bind listener");
        let port = listener.local_addr().expect("local addr").port();

        let server_handle = std::thread::spawn(move || {
            let mut server = loop {
                match listener.accept() {
                    Ok((stream, _)) => match AsyncHttp2Connection::server_handshake(stream) {
                        Ok(conn) => break conn,
                        Err(_) => continue,
                    },
                    Err(_) => std::thread::sleep(Duration::from_millis(5)),
                }
            };

            // Stream 1 request
            for _ in 0..30 {
                match server.recv_frame() {
                    Ok(crate::simd_parser::Http2Frame::Headers { stream_id: 1, .. }) => break,
                    _ => std::thread::sleep(Duration::from_millis(5)),
                }
            }

            // 1. Send PUSH_PROMISE on stream 2 with no-store (RFC 7234 must not store)
            let p_no_store = server.session.create_push_promise(
                1,
                2,
                &[
                    (":method", "GET"),
                    (":path", "/sensitive.json"),
                    (":scheme", "http"),
                ],
            );
            server.send_frame(&p_no_store).expect("send p_no_store");
            let resp_headers_no_store =
                [(":status", "200"), ("cache-control", "no-store, private")];
            server
                .send_response(2, &resp_headers_no_store, Some(b"{\"secret\": 123}"))
                .expect("send 2");

            // 2. Send PUSH_PROMISE on stream 4 with max-age=3600 (RFC 7234 fresh)
            let p_fresh = server.session.create_push_promise(
                1,
                4,
                &[
                    (":method", "GET"),
                    (":path", "/bundle.js"),
                    (":scheme", "http"),
                ],
            );
            server.send_frame(&p_fresh).expect("send p_fresh");
            let resp_headers_fresh = [
                (":status", "200"),
                ("cache-control", "public, max-age=3600"),
                ("etag", "\"bundle-v1\""),
            ];
            server
                .send_response(4, &resp_headers_fresh, Some(b"console.log('bundle');"))
                .expect("send 4");

            // 3. Response on stream 1
            let html_headers = [(":status", "200"), ("content-type", "text/html")];
            server
                .send_response(1, &html_headers, Some(b"<html>ready</html>"))
                .expect("send 1");

            for _ in 0..10 {
                let _ = server.try_recv_frame();
                std::thread::sleep(Duration::from_millis(5));
            }
        });

        let pool = AsyncHttp2Pool::new("127.0.0.1", port, 2).with_push_promises(true);

        // 1. Execute stream 1 request
        let resp = pool
            .execute_request("GET", "/index.html", &[], None)
            .expect("exec index");
        assert_eq!(resp.status.0, 200);

        // /sensitive.json has no-store -> MUST NOT be in cache!
        assert!(!pool.has_cached_push_response("GET", "/sensitive.json"));

        // /bundle.js has max-age=3600 -> MUST be in cache!
        assert!(pool.has_cached_push_response("GET", "/bundle.js"));
        assert_eq!(pool.push_promise_cache_count(), 1);

        // Consume /bundle.js
        let resp_bundle = pool
            .execute_request("GET", "/bundle.js", &[], None)
            .expect("exec bundle");
        assert_eq!(resp_bundle.status.0, 200);
        assert_eq!(resp_bundle.body, b"console.log('bundle');");
        assert_eq!(pool.push_cache_hits(), 1);

        server_handle.join().expect("server join");
    }

    #[test]
    fn test_http2_pool_rfc7232_conditional_revalidation_304() {
        let listener = AsyncTcpListener::bind("127.0.0.1:0").expect("bind listener");
        let port = listener.local_addr().expect("local addr").port();

        let server_handle = std::thread::spawn(move || {
            let mut server = loop {
                match listener.accept() {
                    Ok((stream, _)) => match AsyncHttp2Connection::server_handshake(stream) {
                        Ok(conn) => break conn,
                        Err(_) => continue,
                    },
                    Err(_) => std::thread::sleep(Duration::from_millis(5)),
                }
            };

            // Request 1: Initial GET /api/data
            let mut s1 = 0;
            for _ in 0..30 {
                match server.recv_frame() {
                    Ok(crate::simd_parser::Http2Frame::Headers { stream_id, .. }) => {
                        s1 = stream_id;
                        break;
                    }
                    _ => std::thread::sleep(Duration::from_millis(5)),
                }
            }
            assert_eq!(s1, 1);
            let h1 = [
                (":status", "200"),
                ("etag", "\"v1-hash-abc\""),
                ("cache-control", "public, max-age=60"),
            ];
            server
                .send_response(1, &h1, Some(b"{\"version\": 1, \"status\": \"ok\"}"))
                .expect("send s1 response");

            // Request 2: Revalidation request with If-None-Match
            let mut s2 = 0;
            for _ in 0..30 {
                match server.recv_frame() {
                    Ok(crate::simd_parser::Http2Frame::Headers { stream_id, .. }) => {
                        s2 = stream_id;
                        break;
                    }
                    _ => std::thread::sleep(Duration::from_millis(5)),
                }
            }
            assert_eq!(s2, 3);
            let s2_stream = server
                .session
                .streams
                .get(&3)
                .expect("stream 3 exists in session");
            let if_none_match_found = s2_stream
                .received_headers
                .iter()
                .any(|(k, v)| k.eq_ignore_ascii_case("if-none-match") && v == "\"v1-hash-abc\"");
            assert!(
                if_none_match_found,
                "Server must have received If-None-Match header!"
            );

            // Server replies 304 Not Modified with refreshed Cache-Control
            let h2 = [
                (":status", "304"),
                ("etag", "\"v1-hash-abc\""),
                ("cache-control", "public, max-age=120"),
            ];
            server
                .send_response(3, &h2, None)
                .expect("send 304 response");

            for _ in 0..10 {
                let _ = server.try_recv_frame();
                std::thread::sleep(Duration::from_millis(5));
            }
        });

        let pool = AsyncHttp2Pool::new("127.0.0.1", port, 2).with_http_cache(true);
        assert!(pool.http_cache_enabled());
        assert_eq!(pool.cache_revalidations(), 0);

        // 1. Initial request -> 200 OK stored in client cache
        let resp1 = pool
            .execute_request("GET", "/api/data", &[], None)
            .expect("request 1");
        assert_eq!(resp1.status.0, 200);
        assert_eq!(resp1.body, b"{\"version\": 1, \"status\": \"ok\"}");
        assert_eq!(pool.http_cache_count(), 1);

        // 2. Second request forced with Cache-Control: no-cache to trigger conditional revalidation
        let resp2 = pool
            .execute_request("GET", "/api/data", &[("Cache-Control", "no-cache")], None)
            .expect("request 2 with revalidation");

        // Transparent resolution: client sees 200 OK with cached body and revalidation count incremented!
        assert_eq!(resp2.status.0, 200);
        assert_eq!(resp2.body, b"{\"version\": 1, \"status\": \"ok\"}");
        assert_eq!(pool.cache_revalidations(), 1);
        assert_eq!(pool.stats().cache_revalidations, 1);
        assert_eq!(pool.push_cache_hits(), 1);

        server_handle.join().expect("server join");
    }

    #[test]
    fn test_http2_pool_rfc7234_vary_multi_key_isolation() {
        let listener = AsyncTcpListener::bind("127.0.0.1:0").expect("bind listener");
        let port = listener.local_addr().expect("local addr").port();

        let server_handle = std::thread::spawn(move || {
            let mut server = loop {
                match listener.accept() {
                    Ok((stream, _)) => match AsyncHttp2Connection::server_handshake(stream) {
                        Ok(conn) => break conn,
                        Err(_) => continue,
                    },
                    Err(_) => continue,
                }
            };

            // Request 1: GET /api/resource (Accept-Encoding: gzip) -> Stream 1
            let frame1 = loop {
                if let Some(f) = server.try_recv_frame().expect("recv frame 1") {
                    if matches!(f, crate::simd_parser::Http2Frame::Headers { .. }) {
                        break f;
                    }
                }
                std::thread::sleep(Duration::from_millis(5));
            };
            assert_eq!(frame1.stream_id(), 1);
            let h1 = [
                (":status", "200"),
                ("vary", "Accept-Encoding"),
                ("content-encoding", "gzip"),
                ("cache-control", "public, max-age=120"),
            ];
            server
                .send_response(1, &h1, Some(b"DATA_GZIP"))
                .expect("send 200 gzip");

            // Request 2: GET /api/resource (Accept-Encoding: br) -> Stream 3
            let frame2 = loop {
                if let Some(f) = server.try_recv_frame().expect("recv frame 2") {
                    if matches!(f, crate::simd_parser::Http2Frame::Headers { .. }) {
                        break f;
                    }
                }
                std::thread::sleep(Duration::from_millis(5));
            };
            assert_eq!(frame2.stream_id(), 3);
            let h2 = [
                (":status", "200"),
                ("vary", "Accept-Encoding"),
                ("content-encoding", "br"),
                ("cache-control", "public, max-age=120"),
            ];
            server
                .send_response(3, &h2, Some(b"DATA_BR"))
                .expect("send 200 br");

            // Request 5: GET /wildcard (Vary: *) -> Stream 5
            let frame3 = loop {
                if let Some(f) = server.try_recv_frame().expect("recv frame 3") {
                    if matches!(f, crate::simd_parser::Http2Frame::Headers { .. }) {
                        break f;
                    }
                }
                std::thread::sleep(Duration::from_millis(5));
            };
            assert_eq!(frame3.stream_id(), 5);
            let h3 = [
                (":status", "200"),
                ("vary", "*"),
                ("cache-control", "public, max-age=120"),
            ];
            server
                .send_response(5, &h3, Some(b"WILD1"))
                .expect("send 200 wildcard 1");

            // Request 6: GET /wildcard again (must NOT hit cache because Vary: *) -> Stream 7
            let frame4 = loop {
                if let Some(f) = server.try_recv_frame().expect("recv frame 4") {
                    if matches!(f, crate::simd_parser::Http2Frame::Headers { .. }) {
                        break f;
                    }
                }
                std::thread::sleep(Duration::from_millis(5));
            };
            assert_eq!(frame4.stream_id(), 7);
            let h4 = [
                (":status", "200"),
                ("vary", "*"),
                ("cache-control", "public, max-age=120"),
            ];
            server
                .send_response(7, &h4, Some(b"WILD2"))
                .expect("send 200 wildcard 2");

            for _ in 0..10 {
                let _ = server.try_recv_frame();
                std::thread::sleep(Duration::from_millis(5));
            }
        });

        let pool = AsyncHttp2Pool::new("127.0.0.1", port, 2).with_http_cache(true);

        // 1. First request with Accept-Encoding: gzip
        let resp1 = pool
            .execute_request("GET", "/api/resource", &[("Accept-Encoding", "gzip")], None)
            .expect("request gzip");
        assert_eq!(resp1.status.0, 200);
        assert_eq!(resp1.body, b"DATA_GZIP");
        assert_eq!(pool.http_cache_count(), 1);

        // 2. Second request with Accept-Encoding: br (Vary isolation: gzip entry cannot be reused!)
        let resp2 = pool
            .execute_request("GET", "/api/resource", &[("Accept-Encoding", "br")], None)
            .expect("request br");
        assert_eq!(resp2.status.0, 200);
        assert_eq!(resp2.body, b"DATA_BR");
        // Two distinct variant entries are now cached under /api/resource
        assert_eq!(pool.http_cache_count(), 2);
        assert_eq!(pool.push_cache_hits(), 0);

        // 3. Third request with Accept-Encoding: gzip -> Cache HIT on Variant 1!
        let resp3 = pool
            .execute_request("GET", "/api/resource", &[("Accept-Encoding", "gzip")], None)
            .expect("request gzip cached");
        assert_eq!(resp3.status.0, 200);
        assert_eq!(resp3.body, b"DATA_GZIP");
        assert_eq!(pool.push_cache_hits(), 1);

        // 4. Fourth request with Accept-Encoding: br -> Cache HIT on Variant 2!
        let resp4 = pool
            .execute_request("GET", "/api/resource", &[("Accept-Encoding", "br")], None)
            .expect("request br cached");
        assert_eq!(resp4.status.0, 200);
        assert_eq!(resp4.body, b"DATA_BR");
        assert_eq!(pool.push_cache_hits(), 2);

        // 5. Fifth request for Vary: * resource -> stored but unmatchable under RFC 7234
        let resp_wild1 = pool
            .execute_request("GET", "/wildcard", &[], None)
            .expect("wildcard 1");
        assert_eq!(resp_wild1.status.0, 200);
        assert_eq!(resp_wild1.body, b"WILD1");

        // 6. Sixth request for /wildcard MUST NOT hit cache
        let resp_wild2 = pool
            .execute_request("GET", "/wildcard", &[], None)
            .expect("wildcard 2");
        assert_eq!(resp_wild2.status.0, 200);
        assert_eq!(resp_wild2.body, b"WILD2");
        assert_eq!(pool.push_cache_hits(), 2); // Unchanged

        server_handle.join().expect("server join");
    }

    #[test]
    fn test_http2_pool_stale_while_revalidate_async_background() {
        let listener = AsyncTcpListener::bind("127.0.0.1:0").expect("bind listener");
        let port = listener.local_addr().expect("local addr").port();

        let server_handle = std::thread::spawn(move || {
            let mut server = loop {
                match listener.accept() {
                    Ok((stream, _)) => match AsyncHttp2Connection::server_handshake(stream) {
                        Ok(conn) => break conn,
                        Err(_) => continue,
                    },
                    Err(_) => continue,
                }
            };

            // Request 1: GET /api/swr -> Stream 1
            let frame1 = loop {
                if let Some(f) = server.try_recv_frame().expect("recv frame 1") {
                    if matches!(f, crate::simd_parser::Http2Frame::Headers { .. }) {
                        break f;
                    }
                }
                std::thread::sleep(Duration::from_millis(5));
            };
            assert_eq!(frame1.stream_id(), 1);
            let h1 = [
                (":status", "200"),
                ("etag", "\"v1-swr\""),
                (
                    "cache-control",
                    "public, max-age=1, stale-while-revalidate=60",
                ),
            ];
            server
                .send_response(1, &h1, Some(b"SWR_V1"))
                .expect("send 200 swr 1");

            // Background Revalidation Request: GET /api/swr with If-None-Match: "v1-swr" -> Stream 3
            let frame2 = loop {
                if let Some(f) = server.try_recv_frame().expect("recv frame 2") {
                    if matches!(f, crate::simd_parser::Http2Frame::Headers { .. }) {
                        break f;
                    }
                }
                std::thread::sleep(Duration::from_millis(5));
            };
            assert_eq!(frame2.stream_id(), 3);
            let h2 = [
                (":status", "304"),
                ("etag", "\"v1-swr\""),
                (
                    "cache-control",
                    "public, max-age=120, stale-while-revalidate=60",
                ),
            ];
            server
                .send_response(3, &h2, None)
                .expect("send 304 swr revalidation");

            for _ in 0..10 {
                let _ = server.try_recv_frame();
                std::thread::sleep(Duration::from_millis(5));
            }
        });

        let pool = AsyncHttp2Pool::new("127.0.0.1", port, 2).with_http_cache(true);

        // 1. Initial request -> 200 OK stored in client cache
        let resp1 = pool
            .execute_request("GET", "/api/swr", &[], None)
            .expect("request 1");
        assert_eq!(resp1.status.0, 200);
        assert_eq!(resp1.body, b"SWR_V1");
        assert_eq!(pool.http_cache_count(), 1);
        assert_eq!(pool.stale_hits(), 0);

        // Sleep 1.1s so max-age=1 expires and entry enters stale-while-revalidate window
        std::thread::sleep(Duration::from_millis(1100));

        // 2. Second request -> immediate stale hit (Warning: 110 header present), triggers background revalidation
        let resp2 = pool
            .execute_request("GET", "/api/swr", &[], None)
            .expect("request 2 stale");
        assert_eq!(resp2.status.0, 200);
        assert_eq!(resp2.body, b"SWR_V1");
        assert_eq!(
            resp2.headers.get("warning"),
            Some("110 - \"Response is Stale\"")
        );
        assert_eq!(pool.stale_hits(), 1);

        // Wait up to 1000ms for background revalidation to complete
        let start = std::time::Instant::now();
        while pool.cache_revalidations() == 0 && start.elapsed() < Duration::from_millis(1000) {
            std::thread::sleep(Duration::from_millis(10));
        }

        assert_eq!(pool.cache_revalidations(), 1);
        assert!(pool.background_revalidations() >= 1);

        server_handle.join().expect("server join");
    }

    #[test]
    fn test_http2_pool_stale_if_error_resilience() {
        let listener = AsyncTcpListener::bind("127.0.0.1:0").expect("bind listener");
        let port = listener.local_addr().expect("local addr").port();

        let server_handle = std::thread::spawn(move || {
            let mut server = loop {
                match listener.accept() {
                    Ok((stream, _)) => match AsyncHttp2Connection::server_handshake(stream) {
                        Ok(conn) => break conn,
                        Err(_) => continue,
                    },
                    Err(_) => continue,
                }
            };

            // Request 1: GET /api/sie -> Stream 1
            let frame1 = loop {
                if let Some(f) = server.try_recv_frame().expect("recv frame 1") {
                    if matches!(f, crate::simd_parser::Http2Frame::Headers { .. }) {
                        break f;
                    }
                }
                std::thread::sleep(Duration::from_millis(5));
            };
            assert_eq!(frame1.stream_id(), 1);
            let h1 = [
                (":status", "200"),
                ("cache-control", "public, max-age=1, stale-if-error=120"),
            ];
            server
                .send_response(1, &h1, Some(b"SIE_SAVED_DATA"))
                .expect("send 200 sie 1");

            // Request 2: GET /api/sie -> Stream 3, server replies with 500 Internal Server Error
            let frame2 = loop {
                if let Some(f) = server.try_recv_frame().expect("recv frame 2") {
                    if matches!(f, crate::simd_parser::Http2Frame::Headers { .. }) {
                        break f;
                    }
                }
                std::thread::sleep(Duration::from_millis(5));
            };
            assert_eq!(frame2.stream_id(), 3);
            let h2 = [(":status", "500")];
            server
                .send_response(3, &h2, Some(b"INTERNAL_SERVER_ERROR"))
                .expect("send 500");

            for _ in 0..10 {
                let _ = server.try_recv_frame();
                std::thread::sleep(Duration::from_millis(5));
            }
        });

        let pool = AsyncHttp2Pool::new("127.0.0.1", port, 2).with_http_cache(true);

        // 1. Initial request -> 200 OK stored in client cache
        let resp1 = pool
            .execute_request("GET", "/api/sie", &[], None)
            .expect("request 1");
        assert_eq!(resp1.status.0, 200);
        assert_eq!(resp1.body, b"SIE_SAVED_DATA");

        // Sleep 1.1s so max-age=1 expires
        std::thread::sleep(Duration::from_millis(1100));

        // 2. Second request hits origin 500 error, but stale-if-error rescues it!
        let resp2 = pool
            .execute_request("GET", "/api/sie", &[], None)
            .expect("request 2 rescued by stale-if-error");
        assert_eq!(resp2.status.0, 200);
        assert_eq!(resp2.body, b"SIE_SAVED_DATA");
        assert_eq!(
            resp2.headers.get("warning"),
            Some("110 - \"Response is Stale\"")
        );
        assert_eq!(pool.stale_error_fallbacks(), 1);
        assert_eq!(pool.stats().stale_error_fallbacks, 1);

        server_handle.join().expect("server join");
    }

    #[test]
    fn test_http2_pool_cache_heuristic_freshness() {
        let mut resp = crate::http::HttpResponse::new(crate::http::HttpStatus(200));
        let now = std::time::SystemTime::now();
        let past = now - std::time::Duration::from_secs(1000);
        let past_http_date = crate::http::format_http_date(past);
        resp.headers.set("last-modified", past_http_date.as_str());

        let entry = Http2PoolCacheEntry::new("GET", "/api/heuristic", resp);
        assert!(entry.is_heuristic());
        assert!(entry.is_cacheable());
        // Freshness should be approximately 10% of 1000s = ~100s
        let freshness = entry.heuristic_freshness().expect("heuristic freshness");
        assert!(freshness.as_secs() >= 95 && freshness.as_secs() <= 105);

        // Within freshness window (e.g. at now + 50s): fresh
        assert!(entry.is_fresh(
            now + std::time::Duration::from_secs(50),
            std::time::Duration::from_secs(10)
        ));
        // Past freshness window (e.g. at now + 150s): not fresh
        assert!(!entry.is_fresh(
            now + std::time::Duration::from_secs(150),
            std::time::Duration::from_secs(10)
        ));
    }

    #[test]
    fn test_http2_pool_cache_lru_and_sweep() {
        let pool = AsyncHttp2Pool::new("127.0.0.1", 8080, 2)
            .with_http_cache(true)
            .with_max_http_cache_entries(2);

        assert_eq!(pool.max_http_cache_entries(), 2);
        assert_eq!(pool.http_cache_evictions(), 0);

        let mut r1 = crate::http::HttpResponse::new(crate::http::HttpStatus(200));
        r1.headers.set("cache-control", "public, max-age=60");
        let e1 = Http2PoolCacheEntry::new("GET", "/api/item1", r1);

        let mut r2 = crate::http::HttpResponse::new(crate::http::HttpStatus(200));
        r2.headers.set("cache-control", "public, max-age=60");
        let e2 = Http2PoolCacheEntry::new("GET", "/api/item2", r2);

        let mut r3 = crate::http::HttpResponse::new(crate::http::HttpStatus(200));
        r3.headers.set("cache-control", "public, max-age=60");
        let e3 = Http2PoolCacheEntry::new("GET", "/api/item3", r3);

        // Insert e1 and e2
        pool.insert_http_cache_entry("GET:/api/item1".into(), e1);
        pool.insert_http_cache_entry("GET:/api/item2".into(), e2);
        assert_eq!(pool.http_cache_count(), 2);

        // Access e1 (touch it) so e2 becomes LRU
        if let Ok(mut cache) = pool.http_cache_entries.lock() {
            if let Some(entries) = cache.get_mut("GET:/api/item1") {
                entries[0].touch();
            }
        }

        // Insert e3 -> exceeds capacity 2 -> e2 (LRU) evicted!
        pool.insert_http_cache_entry("GET:/api/item3".into(), e3);
        assert_eq!(pool.http_cache_count(), 2);
        assert_eq!(pool.http_cache_evictions(), 1);
        assert_eq!(pool.stats().http_cache_evictions, 1);

        // Verify e1 and e3 exist, e2 is gone
        if let Ok(cache) = pool.http_cache_entries.lock() {
            assert!(cache.contains_key("GET:/api/item1"));
            assert!(!cache.contains_key("GET:/api/item2"));
            assert!(cache.contains_key("GET:/api/item3"));
        }

        // Test sweep_http_cache with expired TTL
        let future_time = std::time::SystemTime::now() + std::time::Duration::from_secs(100);
        let swept = pool.sweep_http_cache(future_time, std::time::Duration::from_secs(10));
        assert_eq!(swept, 2);
        assert_eq!(pool.http_cache_count(), 0);
        assert_eq!(pool.http_cache_evictions(), 3);
    }

    #[test]
    fn test_http2_pool_cache_invalidation_methods() {
        let pool = AsyncHttp2Pool::new("127.0.0.1", 8080, 2).with_http_cache(true);

        let mut r1 = crate::http::HttpResponse::new(crate::http::HttpStatus(200));
        r1.headers.set("cache-control", "public, max-age=60");
        pool.insert_http_cache_entry(
            "GET:/api/users/1".into(),
            Http2PoolCacheEntry::new("GET", "/api/users/1", r1.clone()),
        );
        pool.insert_http_cache_entry(
            "GET:/api/users/2".into(),
            Http2PoolCacheEntry::new("GET", "/api/users/2", r1.clone()),
        );
        pool.insert_http_cache_entry(
            "GET:/api/products/1".into(),
            Http2PoolCacheEntry::new("GET", "/api/products/1", r1.clone()),
        );
        pool.insert_http_cache_entry(
            "GET:/api/orders/99".into(),
            Http2PoolCacheEntry::new("GET", "/api/orders/99", r1),
        );

        assert_eq!(pool.http_cache_count(), 4);
        assert_eq!(pool.http_cache_invalidations(), 0);

        // 1. Invalidate single path
        let removed_single = pool.invalidate_http_cache_path("/api/products/1");
        assert_eq!(removed_single, 1);
        assert_eq!(pool.http_cache_count(), 3);
        assert_eq!(pool.http_cache_invalidations(), 1);

        // 2. Invalidate prefix
        let removed_prefix = pool.invalidate_http_cache_prefix("/api/users");
        assert_eq!(removed_prefix, 2);
        assert_eq!(pool.http_cache_count(), 1);
        assert_eq!(pool.http_cache_invalidations(), 3);

        // 3. Invalidate matching predicate
        let removed_pred = pool.invalidate_http_cache_matching(|e| e.path.contains("orders"));
        assert_eq!(removed_pred, 1);
        assert_eq!(pool.http_cache_count(), 0);
        assert_eq!(pool.http_cache_invalidations(), 4);
        assert_eq!(pool.stats().http_cache_invalidations, 4);
    }

    #[test]
    fn test_http2_pool_rfc7234_unsafe_method_invalidation_and_heuristic_warning() {
        let listener = AsyncTcpListener::bind("127.0.0.1:0").expect("bind listener");
        let port = listener.local_addr().expect("local addr").port();

        let server_handle = std::thread::spawn(move || {
            let mut server = loop {
                match listener.accept() {
                    Ok((stream, _)) => match AsyncHttp2Connection::server_handshake(stream) {
                        Ok(conn) => break conn,
                        Err(_) => continue,
                    },
                    Err(_) => continue,
                }
            };

            // Request 1: GET /api/record -> Stream 1 (cached)
            let frame1 = loop {
                if let Some(f) = server.try_recv_frame().expect("recv frame 1") {
                    if matches!(f, crate::simd_parser::Http2Frame::Headers { .. }) {
                        break f;
                    }
                }
                std::thread::sleep(Duration::from_millis(5));
            };
            assert_eq!(frame1.stream_id(), 1);
            let h1 = [(":status", "200"), ("cache-control", "public, max-age=120")];
            server
                .send_response(1, &h1, Some(b"INITIAL_RECORD"))
                .expect("send 200");

            // Request 2: POST /api/record -> Stream 3 (non-safe method: RFC 7234 §4.4 invalidates cached URI!)
            let frame2 = loop {
                if let Some(f) = server.try_recv_frame().expect("recv frame 2") {
                    if matches!(f, crate::simd_parser::Http2Frame::Headers { .. }) {
                        break f;
                    }
                }
                std::thread::sleep(Duration::from_millis(5));
            };
            assert_eq!(frame2.stream_id(), 3);
            let h2 = [(":status", "204")];
            server.send_response(3, &h2, None).expect("send 204");

            // Request 3: GET /api/record -> Stream 5 (must hit origin because previous POST invalidated it!)
            let frame3 = loop {
                if let Some(f) = server.try_recv_frame().expect("recv frame 3") {
                    if matches!(f, crate::simd_parser::Http2Frame::Headers { .. }) {
                        break f;
                    }
                }
                std::thread::sleep(Duration::from_millis(5));
            };
            assert_eq!(frame3.stream_id(), 5);
            let h3 = [(":status", "200"), ("cache-control", "public, max-age=120")];
            server
                .send_response(5, &h3, Some(b"UPDATED_RECORD"))
                .expect("send 200 updated");

            for _ in 0..10 {
                let _ = server.try_recv_frame();
                std::thread::sleep(Duration::from_millis(5));
            }
        });

        let pool = AsyncHttp2Pool::new("127.0.0.1", port, 2).with_http_cache(true);

        // 1. GET /api/record -> Cached
        let r1 = pool
            .execute_request("GET", "/api/record", &[], None)
            .expect("get 1");
        assert_eq!(r1.body, b"INITIAL_RECORD");
        assert_eq!(pool.http_cache_count(), 1);

        // 2. POST /api/record -> Success (204 No Content), triggers RFC 7234 §4.4 invalidation
        let r2 = pool
            .execute_request("POST", "/api/record", &[], Some(b"update"))
            .expect("post 1");
        assert_eq!(r2.status.0, 204);
        assert_eq!(pool.http_cache_count(), 0);
        assert_eq!(pool.http_cache_invalidations(), 1);

        // 3. GET /api/record -> Fetched from origin because cache was invalidated
        let r3 = pool
            .execute_request("GET", "/api/record", &[], None)
            .expect("get 2");
        assert_eq!(r3.body, b"UPDATED_RECORD");
        assert_eq!(pool.http_cache_count(), 1);

        server_handle.join().expect("server join");
    }

    #[test]
    fn test_http2_pool_transparent_compression_negotiation_and_decompression() {
        let listener = std::net::TcpListener::bind("127.0.0.1:0").expect("bind listener");
        let port = listener.local_addr().expect("local addr").port();

        let server_handle = std::thread::spawn(move || {
            let (tcp_stream, _) = listener.accept().expect("accept connection");
            let async_stream = AsyncTcpStream::from_std(tcp_stream).expect("async stream");
            let mut server =
                AsyncHttp2Connection::server_handshake(async_stream).expect("server handshake");

            // Request 1: GET /compressed/br
            let frame1 = loop {
                if let Some(f) = server.try_recv_frame().expect("recv frame 1") {
                    if matches!(f, crate::simd_parser::Http2Frame::Headers { .. }) {
                        break f;
                    }
                }
                std::thread::sleep(Duration::from_millis(5));
            };
            assert_eq!(frame1.stream_id(), 1);
            let s1 = server.session.streams.get(&1).expect("stream 1");
            let ae1 = s1
                .received_headers
                .iter()
                .find(|(k, _)| k.eq_ignore_ascii_case("accept-encoding"))
                .map(|(_, v)| v.as_str());
            assert_eq!(ae1, Some("gzip, deflate, br"));

            let br_body =
                crate::http::compress_brotli(b"Hello Brotli Transparent HTTP/2 Response!");
            let h1 = [
                (":status", "200"),
                ("content-encoding", "br"),
                ("cache-control", "public, max-age=120"),
            ];
            server
                .send_response(1, &h1, Some(&br_body))
                .expect("send 200 br");

            // Request 2: GET /compressed/gzip
            let frame2 = loop {
                if let Some(f) = server.try_recv_frame().expect("recv frame 2") {
                    if matches!(f, crate::simd_parser::Http2Frame::Headers { .. }) {
                        break f;
                    }
                }
                std::thread::sleep(Duration::from_millis(5));
            };
            assert_eq!(frame2.stream_id(), 3);
            let gz_body = crate::http::compress_gzip(b"Hello Gzip Transparent HTTP/2 Response!");
            let h2 = [
                (":status", "200"),
                ("content-encoding", "gzip"),
                ("cache-control", "public, max-age=120"),
            ];
            server
                .send_response(3, &h2, Some(&gz_body))
                .expect("send 200 gzip");

            for _ in 0..10 {
                let _ = server.try_recv_frame();
                std::thread::sleep(Duration::from_millis(5));
            }
        });

        let pool = AsyncHttp2Pool::new("127.0.0.1", port, 2)
            .with_http_cache(true)
            .with_auto_decompress(true);

        assert!(pool.auto_decompress());
        assert_eq!(
            pool.accept_encoding(),
            Some("gzip, deflate, br".to_string())
        );

        // 1. Request 1: GET /compressed/br without Accept-Encoding header -> pool auto-injects and transparently decodes br
        let resp1 = pool
            .execute_request("GET", "/compressed/br", &[], None)
            .expect("request br");
        assert_eq!(resp1.status.0, 200);
        assert_eq!(resp1.body, b"Hello Brotli Transparent HTTP/2 Response!");
        assert_eq!(resp1.headers.get("content-encoding"), None);
        assert_eq!(
            resp1.headers.get("content-length"),
            Some(
                b"Hello Brotli Transparent HTTP/2 Response!"
                    .len()
                    .to_string()
                    .as_str()
            )
        );
        assert_eq!(pool.decompressed_responses(), 1);
        assert_eq!(pool.stats().decompressed_responses, 1);
        assert_eq!(pool.http_cache_count(), 1);

        // Subsequent cache hit returns the uncompressed response
        let resp1_cached = pool
            .execute_request("GET", "/compressed/br", &[], None)
            .expect("cached br");
        assert_eq!(
            resp1_cached.body,
            b"Hello Brotli Transparent HTTP/2 Response!"
        );
        assert_eq!(resp1_cached.headers.get("content-encoding"), None);

        // 2. Request 2: GET /compressed/gzip -> transparently decodes gzip
        let resp2 = pool
            .execute_request("GET", "/compressed/gzip", &[], None)
            .expect("request gzip");
        assert_eq!(resp2.status.0, 200);
        assert_eq!(resp2.body, b"Hello Gzip Transparent HTTP/2 Response!");
        assert_eq!(resp2.headers.get("content-encoding"), None);
        assert_eq!(pool.decompressed_responses(), 2);

        server_handle.join().expect("server join");
    }

    #[test]
    fn test_http2_pool_cache_entry_decompression_methods() {
        let compressed_resp = crate::http::HttpResponse::ok()
            .text("Payload inside Http2PoolCacheEntry")
            .brotli();
        let mut entry = Http2PoolCacheEntry::new("GET", "/cached/entry", compressed_resp);

        assert!(entry.is_compressed());
        assert_eq!(
            entry.content_encoding(),
            crate::http::ContentEncoding::Brotli
        );
        assert_eq!(entry.response.headers.get("content-encoding"), Some("br"));

        let decompressed = entry
            .decompress_in_place()
            .expect("decompress entry in place");
        assert!(decompressed);
        assert!(!entry.is_compressed());
        assert_eq!(
            entry.content_encoding(),
            crate::http::ContentEncoding::Identity
        );
        assert_eq!(entry.response.headers.get("content-encoding"), None);
        assert_eq!(entry.response.body, b"Payload inside Http2PoolCacheEntry");
    }

    #[test]
    fn test_alt_svc_route_metrics_ewma_and_jitter_calculation() {
        let mut metrics = AltSvcRouteMetrics::new("h3://127.0.0.1:50443");
        assert_eq!(metrics.sample_count, 0);
        assert_eq!(metrics.jitter(), Duration::from_millis(0));
        assert_eq!(metrics.failure_rate(), 0.0);

        // First sample: RTT = 100ms
        metrics.record_sample(Duration::from_millis(100));
        assert_eq!(metrics.sample_count, 1);
        assert_eq!(metrics.smoothed_rtt(), Duration::from_millis(100));
        // RFC 6298: rttvar = sample / 2 = 50ms
        assert_eq!(metrics.jitter(), Duration::from_millis(50));
        assert_eq!(metrics.min_rtt, Duration::from_millis(100));
        assert_eq!(metrics.max_rtt, Duration::from_millis(100));
        assert_eq!(metrics.effective_latency(), Duration::from_millis(150));

        // Second sample: RTT = 60ms
        // diff = |100 - 60| = 40ms
        // rttvar = (3 * 50 + 40) / 4 = 190 / 4 = 47.5ms (47ms or 47500us)
        // smoothed_rtt = (7 * 100 + 60) / 8 = 760 / 8 = 95ms
        metrics.record_sample(Duration::from_millis(60));
        assert_eq!(metrics.sample_count, 2);
        assert_eq!(metrics.smoothed_rtt(), Duration::from_millis(95));
        assert_eq!(metrics.jitter(), Duration::from_micros(47500));
        assert_eq!(metrics.min_rtt, Duration::from_millis(60));
        assert_eq!(metrics.max_rtt, Duration::from_millis(100));

        // Record a failure
        metrics.record_failure();
        assert_eq!(metrics.failure_count, 1);
        assert_eq!(metrics.success_count, 2);
        assert!((metrics.failure_rate() - (1.0 / 3.0)).abs() < 1e-4);
    }

    #[test]
    fn test_alt_svc_selection_strategies_and_routing_decision() {
        let pool = AsyncHttp2Pool::new("127.0.0.1", 8443, 2);
        let h2_key = "h2://127.0.0.1:8443";
        let h3_key = "h3://127.0.0.1:50443";

        // Baseline: PreferAltSvc (default)
        assert_eq!(
            pool.alt_svc_selection_strategy(),
            AltSvcSelectionStrategy::PreferAltSvc
        );
        assert!(pool.should_migrate_to_alt_svc(h3_key));

        // Seed initial metrics:
        // H2 native: 30ms RTT, jitter 5ms
        // H3 alternative: 80ms RTT (higher latency), jitter 25ms (higher jitter)
        pool.record_alt_svc_metric(h2_key, Duration::from_millis(30));
        pool.record_alt_svc_metric(h3_key, Duration::from_millis(80));

        // 1. LowestLatency strategy: H2 (30ms) is faster than H3 (80ms) -> do NOT migrate!
        pool.set_alt_svc_selection_strategy(AltSvcSelectionStrategy::LowestLatency);
        assert!(!pool.should_migrate_to_alt_svc(h3_key));

        // If H3 improves and records multiple fast samples (e.g. 10ms)
        for _ in 0..10 {
            pool.record_alt_svc_metric(h3_key, Duration::from_millis(10));
        }
        let m3 = pool.get_alt_svc_metric(h3_key).expect("h3 metric");
        assert!(m3.smoothed_rtt() < Duration::from_millis(30));
        assert!(pool.should_migrate_to_alt_svc(h3_key));

        // 2. LowestJitter strategy
        pool.clear_alt_svc_metrics();
        // H2: first sample 40ms -> jitter = 20ms; second sample 40ms -> jitter = 15ms
        pool.record_alt_svc_metric(h2_key, Duration::from_millis(40));
        pool.record_alt_svc_metric(h2_key, Duration::from_millis(40));
        // H3: first sample 40ms -> jitter = 20ms; second sample 100ms -> jitter = (3*20 + 60)/4 = 30ms
        pool.record_alt_svc_metric(h3_key, Duration::from_millis(40));
        pool.record_alt_svc_metric(h3_key, Duration::from_millis(100));

        pool.set_alt_svc_selection_strategy(AltSvcSelectionStrategy::LowestJitter);
        assert!(!pool.should_migrate_to_alt_svc(h3_key));

        // 3. JitterThreshold strategy: threshold 25ms -> H3 jitter is 30ms (> 25ms) -> rejected
        pool.set_alt_svc_selection_strategy(AltSvcSelectionStrategy::JitterThreshold(
            Duration::from_millis(25),
        ));
        assert!(!pool.should_migrate_to_alt_svc(h3_key));

        pool.set_alt_svc_selection_strategy(AltSvcSelectionStrategy::JitterThreshold(
            Duration::from_millis(35),
        ));
        assert!(pool.should_migrate_to_alt_svc(h3_key));

        // 4. MaxLatencyPenalty strategy
        pool.clear_alt_svc_metrics();
        pool.record_alt_svc_metric(h2_key, Duration::from_millis(50));
        pool.record_alt_svc_metric(h3_key, Duration::from_millis(70)); // +20ms penalty

        pool.set_alt_svc_selection_strategy(AltSvcSelectionStrategy::MaxLatencyPenalty(
            Duration::from_millis(10),
        ));
        assert!(!pool.should_migrate_to_alt_svc(h3_key)); // 20ms > 10ms penalty -> false

        pool.set_alt_svc_selection_strategy(AltSvcSelectionStrategy::MaxLatencyPenalty(
            Duration::from_millis(30),
        ));
        assert!(pool.should_migrate_to_alt_svc(h3_key)); // 20ms <= 30ms penalty -> true

        // 5. Quarantined route is always rejected regardless of metrics
        pool.quarantine_alt_svc_route(h3_key, Some(Duration::from_secs(60)));
        assert!(!pool.should_migrate_to_alt_svc(h3_key));
    }

    #[test]
    fn test_select_best_alt_svc_route_ordering_by_metrics() {
        let pool = AsyncHttp2Pool::new("127.0.0.1", 8443, 2)
            .with_alt_svc_selection_strategy(AltSvcSelectionStrategy::LowestLatency);

        let r1 = crate::simd_parser::AltSvcRoute::new("h3", "alt1.example.com", 443);
        let r2 = crate::simd_parser::AltSvcRoute::new("h3", "alt2.example.com", 443);
        pool.record_alt_svc_routes("127.0.0.1:8443", vec![r1, r2]);

        // Route 1: 90ms latency
        pool.record_alt_svc_metric("h3://alt1.example.com:443", Duration::from_millis(90));
        // Route 2: 25ms latency
        pool.record_alt_svc_metric("h3://alt2.example.com:443", Duration::from_millis(25));

        let best = pool
            .select_best_alt_svc_route(None, "h3", Duration::ZERO, true)
            .expect("best route found");
        assert_eq!(best.host, "alt2.example.com");
    }

    #[test]
    fn test_http2_pool_dynamic_alt_svc_telemetry_integration() {
        let listener = std::net::TcpListener::bind("127.0.0.1:0").expect("bind listener");
        let port = listener.local_addr().expect("local addr").port();

        let handle = std::thread::spawn(move || {
            let (tcp_stream, _) = listener.accept().expect("accept connection");
            let async_stream = AsyncTcpStream::from_std(tcp_stream).expect("async stream");
            let mut server =
                AsyncHttp2Connection::server_handshake(async_stream).expect("server handshake");

            for _ in 0..2 {
                while let Ok(frame) = server.recv_frame() {
                    if let crate::simd_parser::Http2Frame::Headers {
                        stream_id,
                        end_stream,
                        ..
                    } = frame
                    {
                        if end_stream {
                            server
                                .send_response(
                                    stream_id,
                                    &[(":status", "200"), ("alt-svc", "h3=\":50443\"; ma=86400")],
                                    Some(b"h2-response"),
                                )
                                .expect("send response");
                            break;
                        }
                    }
                }
            }
        });

        let h3_dispatches = std::sync::Arc::new(std::sync::atomic::AtomicUsize::new(0));
        let h3_clone = h3_dispatches.clone();

        let pool = AsyncHttp2Pool::new("127.0.0.1", port, 2)
            .with_http3_handler(
                move |_h: &str,
                      _p: u16,
                      _m: &str,
                      _path: &str,
                      _headers: &[(&str, &str)],
                      _b: Option<&[u8]>| {
                    h3_clone.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
                    std::thread::sleep(Duration::from_millis(2));
                    let mut resp = crate::http::HttpResponse::new(crate::http::HttpStatus(200));
                    resp.body = b"h3-response".to_vec();
                    Ok(resp)
                },
            )
            .with_alt_svc_selection_strategy(AltSvcSelectionStrategy::LowestLatency);

        // 1. Initial request goes over HTTP/2 and records H2 latency metric
        let resp1 = pool
            .execute_request("GET", "/initial", &[], None)
            .expect("first req");
        assert_eq!(resp1.body, b"h2-response");

        let h2_metric = pool
            .get_alt_svc_metric(&format!("h2://127.0.0.1:{}", port))
            .expect("h2 metric recorded");
        assert_eq!(h2_metric.sample_count, 1);
        assert!(h2_metric.smoothed_rtt() > Duration::ZERO);

        // 2. Second request: H3 has 0 samples, so probe request goes over H3
        let resp2 = pool
            .execute_request("GET", "/probe-h3", &[], None)
            .expect("second req");
        assert_eq!(resp2.body, b"h3-response");
        assert_eq!(h3_dispatches.load(std::sync::atomic::Ordering::SeqCst), 1);

        let h3_metric = pool
            .get_alt_svc_metric("h3://127.0.0.1:50443")
            .expect("h3 metric recorded");
        assert_eq!(h3_metric.sample_count, 1);
        assert!(h3_metric.smoothed_rtt() >= Duration::from_millis(1));

        // 3. Now verify metrics list snapshot
        let all_metrics = pool.all_alt_svc_metrics();
        assert_eq!(all_metrics.len(), 2);

        // If we artificially force H3 to have very high latency
        for _ in 0..5 {
            pool.record_alt_svc_metric("h3://127.0.0.1:50443", Duration::from_millis(500));
        }
        // H3 is now significantly slower than H2. Under LowestLatency, subsequent requests prefer H2!
        let resp3 = pool
            .execute_request("GET", "/back-to-h2", &[], None)
            .expect("third req");
        assert_eq!(resp3.body, b"h2-response");
        // H3 dispatch count did NOT increase
        assert_eq!(h3_dispatches.load(std::sync::atomic::Ordering::SeqCst), 1);

        pool.shutdown();
        let _ = handle.join();
    }

    #[test]
    fn test_async_http2_connection_send_frame_batch() {
        let listener = std::net::TcpListener::bind("127.0.0.1:0").expect("bind listener");
        let port = listener.local_addr().expect("local addr").port();

        let handle = std::thread::spawn(move || {
            let (tcp_stream, _) = listener.accept().expect("accept connection");
            let async_stream = AsyncTcpStream::from_std(tcp_stream).expect("async stream");
            let mut server =
                AsyncHttp2Connection::server_handshake(async_stream).expect("server handshake");

            let mut got_headers = false;
            let mut got_data = false;
            let start = std::time::Instant::now();
            while start.elapsed() < std::time::Duration::from_secs(10) {
                match server.recv_frame() {
                    Ok(crate::simd_parser::Http2Frame::Headers { .. }) => {
                        got_headers = true;
                    }
                    Ok(crate::simd_parser::Http2Frame::Data {
                        stream_id, data, ..
                    }) => {
                        got_data = true;
                        assert_eq!(data, b"high-frequency-batch-body");
                        server
                            .send_response(
                                stream_id,
                                &[(":status", "200")],
                                Some(b"batch-received"),
                            )
                            .expect("send response");
                        for _ in 0..20 {
                            let _ = server.try_recv_frame();
                            std::thread::sleep(std::time::Duration::from_millis(5));
                        }
                        break;
                    }
                    Ok(_) => {}
                    Err(e) if e.kind() == std::io::ErrorKind::WouldBlock => {
                        std::thread::sleep(std::time::Duration::from_millis(10));
                    }
                    Err(_) => break,
                }
            }
            assert!(got_headers);
            assert!(got_data);
        });

        let client_stream =
            AsyncTcpStream::connect(format!("127.0.0.1:{}", port)).expect("connect client");
        let mut client =
            AsyncHttp2Connection::client_handshake(client_stream).expect("client handshake");

        // Encode request headers and data frame in a batch
        let mut hpack_ctx = crate::simd_parser::HpackContext::new(4096);
        let mut header_block = Vec::new();
        hpack_ctx.encode_headers_into(
            &[
                (":method", "POST"),
                (":path", "/batch-stream"),
                (":scheme", "https"),
            ],
            false,
            &mut header_block,
        );

        let req_headers_frame = crate::simd_parser::Http2Frame::Headers {
            stream_id: 1,
            end_stream: false,
            end_headers: true,
            header_block,
        };
        let req_data_frame = crate::simd_parser::Http2Frame::Data {
            stream_id: 1,
            end_stream: true,
            data: b"high-frequency-batch-body".to_vec(),
        };

        let mut batch = crate::simd_parser::Http2FrameBatchSerializer::new();
        batch.push_frame(&req_headers_frame);
        batch.push_frame(&req_data_frame);

        client.send_frame_batch(&batch).expect("send frame batch");

        // Receive response
        let mut got_resp_data = false;
        let start = std::time::Instant::now();
        while start.elapsed() < std::time::Duration::from_secs(10) {
            match client.recv_frame() {
                Ok(crate::simd_parser::Http2Frame::Data { data, .. }) => {
                    assert_eq!(data, b"batch-received");
                    got_resp_data = true;
                    break;
                }
                Ok(_) => {}
                Err(e) if e.kind() == std::io::ErrorKind::WouldBlock => {
                    std::thread::sleep(std::time::Duration::from_millis(10));
                }
                Err(_) => {
                    std::thread::sleep(std::time::Duration::from_millis(10));
                }
            }
        }
        assert!(got_resp_data);

        let _ = handle.join();
    }

    #[test]
    fn test_async_http2_midstream_priority_update_bandwidth_stealing() {
        let listener = AsyncTcpListener::bind("127.0.0.1:0").expect("bind listener");
        let port = listener.local_addr().unwrap().port();

        let (tx, rx) = std::sync::mpsc::channel();

        let server_handle = std::thread::spawn(move || {
            let mut server = loop {
                match listener.accept() {
                    Ok((stream, _)) => match AsyncHttp2Connection::server_handshake(stream) {
                        Ok(conn) => break conn,
                        Err(_) => continue,
                    },
                    Err(_) => {
                        std::thread::sleep(Duration::from_millis(5));
                        continue;
                    }
                }
            };

            // Setup internal state on server:
            // Stream 3 has accumulated DRR deficit and pending data
            server.session.drr_deficits.insert(3, 4096);
            server.session.set_stream_priority_parameters(
                3,
                crate::simd_parser::PriorityParameters::new(4, true),
            );
            server
                .session
                .pending_outbound_data
                .insert(3, vec![3u8; 40960]);

            // Stream 1 has pending data and is at low priority (urgency 5)
            server.session.drr_deficits.insert(1, 0);
            server.session.set_stream_priority_parameters(
                1,
                crate::simd_parser::PriorityParameters::new(5, true),
            );
            // Total pending across streams: 32768 + 40960 = 73728 bytes, which exceeds
            // the HTTP/2 default connection window (65535 bytes), establishing true network contention.
            server
                .session
                .pending_outbound_data
                .insert(1, vec![1u8; 32768]);

            // Wait for PRIORITY_UPDATE from client
            let mut got_pu = false;
            while !got_pu {
                match server.recv_frame() {
                    Ok(crate::simd_parser::Http2Frame::PriorityUpdate {
                        prioritized_stream_id,
                        ..
                    }) => {
                        assert_eq!(prioritized_stream_id, 1);
                        got_pu = true;
                    }
                    Ok(crate::simd_parser::Http2Frame::GoAway { .. }) => break,
                    _ => {}
                }
            }

            // Verify server dynamic bandwidth reallocation report
            let report = server
                .last_reallocation_report()
                .cloned()
                .expect("reallocation report");
            let _ = tx.send(report);

            // Send response back
            let _ = server.send_frame(&crate::simd_parser::Http2Frame::GoAway {
                last_stream_id: 1,
                error_code: crate::simd_parser::Http2ErrorCode::NoError,
                debug_data: b"done".to_vec(),
            });
        });

        std::thread::sleep(Duration::from_millis(15));

        let client_stream =
            AsyncTcpStream::connect(format!("127.0.0.1:{}", port)).expect("connect client");
        let mut client =
            AsyncHttp2Connection::client_handshake(client_stream).expect("client handshake");

        // Client sends mid-stream PRIORITY_UPDATE for stream 1 promoting to urgency 0
        let reprioritize_report = client
            .reprioritize_stream(1, crate::simd_parser::PriorityParameters::new(0, true))
            .expect("send priority update");
        assert_eq!(reprioritize_report.stream_id, 1);
        assert_eq!(reprioritize_report.new_priority.urgency, 0);

        // Receive report recorded on server
        let server_report = rx
            .recv_timeout(Duration::from_secs(5))
            .expect("receive server report");
        assert_eq!(server_report.stream_id, 1);
        assert_eq!(server_report.old_priority.urgency, 5);
        assert_eq!(server_report.new_priority.urgency, 0);
        assert!(server_report.connection_under_contention);
        assert_eq!(server_report.stolen_bytes, 4096);
        assert_eq!(server_report.donors, vec![(3, 4096)]);
        assert_eq!(
            server_report.total_deficits_before,
            server_report.total_deficits_after
        );

        let _ = server_handle.join();
    }

    #[test]
    fn test_inter_session_drr_fairness_http2_and_http3() {
        let mut arb = InterSessionDrrArbitrator::new(1024);
        let origin = "https://api.example.com:443";

        // Register Session 1 (HTTP/2, weight 1) and Session 2 (HTTP/3, weight 1)
        arb.register_session(1, origin, TransportProtocol::Http2, 1);
        arb.register_session(2, origin, TransportProtocol::Http3, 1);

        assert_eq!(arb.sessions_count(), 2);
        assert_eq!(arb.origins_count(), 1);

        // Both sessions have 4096 pending bytes
        arb.set_session_pending_bytes(1, 4096);
        arb.set_session_pending_bytes(2, 4096);
        assert_eq!(arb.total_pending_bytes(), 8192);

        // Schedule a round with 2048 bytes capacity (quantum 1024 for each session)
        let report = arb.schedule_round(2048);
        assert_eq!(report.total_round_capacity, 2048);
        assert_eq!(report.total_allocated_bytes, 2048);
        assert_eq!(report.slices.len(), 2);

        // Verify fair allocation: Session 1 gets 1024 bytes, Session 2 gets 1024 bytes
        assert_eq!(report.slices[0].session_id, 1);
        assert_eq!(report.slices[0].protocol, TransportProtocol::Http2);
        assert_eq!(report.slices[0].allocated_bytes, 1024);
        assert_eq!(report.slices[0].remaining_pending_bytes, 3072);

        assert_eq!(report.slices[1].session_id, 2);
        assert_eq!(report.slices[1].protocol, TransportProtocol::Http3);
        assert_eq!(report.slices[1].allocated_bytes, 1024);
        assert_eq!(report.slices[1].remaining_pending_bytes, 3072);

        assert_eq!(arb.total_pending_bytes(), 6144);
    }

    #[test]
    fn test_inter_session_hierarchical_multi_origin_bandwidth_quota() {
        let mut arb = InterSessionDrrArbitrator::new(1024);

        let origin_api = "https://api.example.com";
        let origin_cdn = "https://static.cdn.com";

        // API origin is capped at 2048 bytes per round
        arb.configure_origin_quota(origin_api, 2048, 1024, 1);
        // CDN origin has a higher cap of 8192 bytes per round
        arb.configure_origin_quota(origin_cdn, 8192, 1024, 1);

        arb.register_session(10, origin_api, TransportProtocol::Http2, 1);
        arb.register_session(20, origin_cdn, TransportProtocol::Http3, 1);

        // API has 10000 pending bytes; CDN has 20000 pending bytes
        arb.set_session_pending_bytes(10, 10000);
        arb.set_session_pending_bytes(20, 20000);

        // Global round capacity is 15000 bytes
        let report = arb.schedule_round(15000);

        let api_allocated: usize = report
            .slices
            .iter()
            .filter(|s| s.origin == origin_api)
            .map(|s| s.allocated_bytes)
            .sum();

        let cdn_allocated: usize = report
            .slices
            .iter()
            .filter(|s| s.origin == origin_cdn)
            .map(|s| s.allocated_bytes)
            .sum();

        // API must not exceed its configured quota of 2048
        assert!(
            api_allocated <= 2048,
            "api exceeded quota: {}",
            api_allocated
        );
        assert_eq!(api_allocated, 2048);

        // CDN must not exceed its configured quota of 8192
        assert!(
            cdn_allocated <= 8192,
            "cdn exceeded quota: {}",
            cdn_allocated
        );
        assert_eq!(cdn_allocated, 8192);

        assert_eq!(report.total_allocated_bytes, api_allocated + cdn_allocated);
    }

    #[test]
    fn test_inter_session_inter_host_starvation_prevention() {
        let mut arb = InterSessionDrrArbitrator::new(1024).with_starvation_threshold(2);

        let origin_dominant = "https://heavy.example.com";
        let origin_starved = "https://light.example.com";

        arb.configure_origin_quota(origin_dominant, 8192, 1024, 1);
        arb.configure_origin_quota(origin_starved, 4096, 2048, 1);

        arb.register_session(100, origin_dominant, TransportProtocol::Http2, 1);
        arb.register_session(200, origin_starved, TransportProtocol::Http3, 1);

        // Manually simulate that light.example.com was starved for 2 rounds
        if let Some(quota) = arb.origins.get_mut(origin_starved) {
            quota.consecutive_starved_rounds = 2;
        }
        if let Some(sess) = arb.sessions.get_mut(&200) {
            sess.consecutive_starved_rounds = 2;
        }

        arb.set_session_pending_bytes(100, 10000);
        arb.set_session_pending_bytes(200, 2048);

        // Execute scheduling round with 4096 bytes capacity
        let report = arb.schedule_round(4096);

        // Anti-starvation boost must be triggered for origin_starved and session 200
        assert_eq!(
            report.starved_origins_boosted,
            vec![origin_starved.to_string()]
        );
        assert_eq!(report.starved_sessions_boosted, vec![200]);

        // The first slice must belong to the boosted starved session with anti_starvation_boost_applied = true
        let boosted_slice = report
            .slices
            .iter()
            .find(|s| s.session_id == 200)
            .expect("starved session served");
        assert!(boosted_slice.anti_starvation_boost_applied);
        assert_eq!(boosted_slice.allocated_bytes, 2048);
        assert_eq!(boosted_slice.remaining_pending_bytes, 0);

        // Consecutive starved rounds counter must be reset to 0
        assert_eq!(
            arb.get_origin_quota(origin_starved)
                .unwrap()
                .consecutive_starved_rounds,
            0
        );
        assert_eq!(arb.get_session(200).unwrap().consecutive_starved_rounds, 0);
    }

    #[test]
    fn test_inter_session_drr_empty_queue_deficit_reset() {
        let mut arb = InterSessionDrrArbitrator::new(2048);
        let origin = "https://drain.example.com";

        arb.register_session(1, origin, TransportProtocol::Http2, 1);

        // Session has 500 bytes pending (less than quantum of 2048)
        arb.set_session_pending_bytes(1, 500);

        let report = arb.schedule_round(4096);
        assert_eq!(report.total_allocated_bytes, 500);

        // Since session is now completely drained, its deficit must be 0 (RFC DRR property)
        let sess = arb.get_session(1).unwrap();
        assert_eq!(sess.pending_bytes, 0);
        assert_eq!(sess.deficit, 0);
    }

    #[test]
    fn test_async_http2_pool_inter_session_arbitration_integration() {
        let pool = AsyncHttp2Pool::new("127.0.0.1", 8080, 2);

        // Configure origin quota via pool
        pool.configure_origin_quota("https://api.mycorp.org", 4096, 1024, 2);

        // Register HTTP/2 and HTTP/3 transport sessions via pool
        pool.register_transport_session(101, "https://api.mycorp.org", TransportProtocol::Http2, 1);
        pool.register_transport_session(102, "https://api.mycorp.org", TransportProtocol::Http3, 2);

        // Update pending payload queues
        pool.update_session_pending_data(101, 2048);
        pool.update_session_pending_data(102, 4096);

        // Perform pool-level inter-session fair scheduling
        let report = pool.schedule_inter_session_bandwidth(3072);
        assert_eq!(report.total_round_capacity, 3072);
        assert!(report.total_allocated_bytes > 0);
        assert!(!report.slices.is_empty());

        // Both HTTP/2 and HTTP/3 received bandwidth allocations
        let has_h2 = report
            .slices
            .iter()
            .any(|s| s.protocol == TransportProtocol::Http2);
        let has_h3 = report
            .slices
            .iter()
            .any(|s| s.protocol == TransportProtocol::Http3);
        assert!(has_h2);
        assert!(has_h3);

        // Clean up session unregistration
        pool.unregister_transport_session(101);
        pool.unregister_transport_session(102);
    }

    #[test]
    fn test_inter_session_ewma_throughput_and_saturation_tracking() {
        let mut arb =
            InterSessionDrrArbitrator::new(1024).with_adaptive_quantum(false, 256, 4096, 0.5);

        let origin = "https://metrics.example.com";
        arb.register_session(1, origin, TransportProtocol::Http2, 1);

        // Round 1: High saturation (100% capacity consumed)
        arb.set_session_pending_bytes(1, 10000);
        let report1 = arb.schedule_round(2048);
        assert_eq!(report1.total_allocated_bytes, 2048);
        assert_eq!(report1.saturation_level, NetworkSaturationLevel::Saturated);
        assert_eq!(arb.saturation_level(), NetworkSaturationLevel::Saturated);
        assert_eq!(arb.ewma_throughput(), 2048.0);
        assert!((arb.ewma_saturation_ratio() - 1.0).abs() < 1e-4);

        // Round 2: Optimal load (60% capacity consumed)
        // 2000 capacity, session has 1200 pending bytes
        arb.set_session_pending_bytes(1, 1200);
        let report2 = arb.schedule_round(2000);
        assert_eq!(report2.total_allocated_bytes, 1200);
        assert_eq!(report2.saturation_level, NetworkSaturationLevel::Optimal);
        assert_eq!(arb.saturation_level(), NetworkSaturationLevel::Optimal);
        // EWMA with alpha = 0.5: 0.5 * 2048 + 0.5 * 1200 = 1624
        assert!((arb.ewma_throughput() - 1624.0).abs() < 1e-4);
        // EWMA saturation ratio: 0.5 * 1.0 + 0.5 * (1200/2000 = 0.6) = 0.8
        assert!((arb.ewma_saturation_ratio() - 0.8).abs() < 1e-4);

        // Round 3: Light load / Under-utilized (10% capacity consumed)
        arb.set_session_pending_bytes(1, 200);
        let report3 = arb.schedule_round(2000);
        assert_eq!(report3.total_allocated_bytes, 200);
        assert_eq!(
            report3.saturation_level,
            NetworkSaturationLevel::UnderUtilized
        );
        assert_eq!(
            arb.saturation_level(),
            NetworkSaturationLevel::UnderUtilized
        );
        // EWMA: 0.5 * 1624 + 0.5 * 200 = 912
        assert!((arb.ewma_throughput() - 912.0).abs() < 1e-4);
    }

    #[test]
    fn test_inter_session_adaptive_drr_quantum_regulation() {
        // Start with base quantum = 1024, min = 256, max = 2048, adaptive = true
        let mut arb =
            InterSessionDrrArbitrator::new(1024).with_adaptive_quantum(true, 256, 2048, 0.2);

        let origin = "https://stream.example.com";
        arb.register_session(1, origin, TransportProtocol::Http2, 1);
        arb.set_session_pending_bytes(1, 100000);

        // Round 1 under saturation: initial quantum is 1024.
        // Under saturation, quantum must be dynamically reduced: step = max(1024/4, 64) = 256 -> new base = 768.
        let report1 = arb.schedule_round(4096);
        assert_eq!(report1.effective_base_quantum, 1024);
        assert_eq!(arb.base_quantum(), 768);

        // Round 2 under continued saturation: 768 - max(768/4, 64) = 768 - 192 = 576.
        let report2 = arb.schedule_round(4096);
        assert_eq!(report2.effective_base_quantum, 768);
        assert_eq!(arb.base_quantum(), 576);

        // Multiple saturated rounds drive quantum down to min_base_quantum (256)
        for _ in 0..5 {
            arb.schedule_round(4096);
        }
        assert_eq!(arb.base_quantum(), 256);

        // Now drain pending data and test light load scaling up
        arb.set_session_pending_bytes(1, 10);
        // Round under light load (10 bytes out of 10000 -> UnderUtilized)
        // Quantum scales up: 256 + 64 = 320
        arb.schedule_round(10000);
        assert!(arb.base_quantum() > 256);
    }

    #[test]
    fn test_inter_session_jains_fairness_index_computation() {
        let mut arb = InterSessionDrrArbitrator::new(1024);
        let origin_a = "https://host-a.com";
        let origin_b = "https://host-b.com";

        // Equal weights and equal quotas
        arb.configure_origin_quota(origin_a, 4096, 1024, 1);
        arb.configure_origin_quota(origin_b, 4096, 1024, 1);

        arb.register_session(1, origin_a, TransportProtocol::Http2, 1);
        arb.register_session(2, origin_b, TransportProtocol::Http3, 1);

        arb.set_session_pending_bytes(1, 2048);
        arb.set_session_pending_bytes(2, 2048);

        // Schedule round with 2048 bytes capacity -> each gets 1024 bytes
        let report = arb.schedule_round(2048);
        assert_eq!(report.slices.len(), 2);
        assert_eq!(report.slices[0].allocated_bytes, 1024);
        assert_eq!(report.slices[1].allocated_bytes, 1024);

        // Jain's fairness index for equal allocation across 2 equal-weighted origins must be exactly 1.0
        assert!((report.jains_fairness_index - 1.0).abs() < 1e-4);
        assert!((arb.jains_fairness_index() - 1.0).abs() < 1e-4);

        // Telemetry export
        let telem = arb.export_fairness_telemetry();
        assert_eq!(telem.origin_metrics.len(), 2);
        assert!((telem.jains_fairness_index - 1.0).abs() < 1e-4);
        assert_eq!(telem.total_active_sessions, 2);
    }

